arguments.new_str:
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class PredictionController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly string[] _labels;

    public PredictionController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        IConfiguration configuration)
    {
        _predictionPool = predictionPool;

        var modelPath = configuration["ModelPath"]!;
        var mlContext = new MLContext();
        var model = mlContext.Model.Load(modelPath, out _);

        var labelColumn = model.GetOutputSchema(SchemaDefinition.Create(typeof(TicketInput)))
            .GetColumnOrNull("PredictedLabel");

        // Extract label names via VBuffer from the Score column's slot names
        var scoreColumn = model.GetOutputSchema(SchemaDefinition.Create(typeof(TicketInput)))["Score"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.GetSlotNames(ref slotNames);
        _labels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }

    [HttpPost]
    public ActionResult<PredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var probabilities = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _labels.Length; i++)
            probabilities[_labels[i]] = prediction.Score[i];

        return Ok(new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Probabilities = probabilities
        });
    }
}

